def build_workbook(rows):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "QA Checklist"
    ws.column_dimensions["A"].width = 8
    ws.column_dimensions["B"].width = 60
    ws.column_dimensions["C"].width = 10
    ws.column_dimensions["D"].width = 95
    ws.column_dimensions["E"].width = 30
    r = 1
    for row in rows:
        kind = row[0]
        if kind == "HEADER":
            ws.cell(row=r, column=1, value=row[1])
            ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=5)
            ws.cell(row=r, column=1).font = Font(bold=True)
            ws.cell(row=r, column=1).alignment = Alignment(wrap_text=True)
            r += 1
            continue
        if kind == "SECTION":
            ws.cell(row=r, column=1, value=row[1])
            ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=5)
            ws.cell(row=r, column=1).font = Font(bold=True)
            for col in range(1, 6):
                ws.cell(row=r, column=col).fill = HDR_FILL
            r += 1
            continue
        item, check, status, evidence, verifier = row
        for col, val in enumerate((item, check, status, evidence, verifier), start=1):
            c = ws.cell(row=r, column=col, value=val)
            c.alignment = Alignment(wrap_text=True, vertical="top")
        if status == "Fail":
            for col in range(1, 6):
                ws.cell(row=r, column=col).fill = FAIL_FILL
        elif status == "Flag":
            for col in range(1, 6):
                ws.cell(row=r, column=col).fill = FLAG_FILL
                ws.cell(row=r, column=col).font = Font(color="996600")
        elif status == "N/A":
            for col in range(1, 6):
                ws.cell(row=r, column=col).font = NA_FONT
        r += 1
    return wb


if __name__ == "__main__":
    build_with_validation(rows=ROWS, source_reads_path=SOURCE_READS, out_path=OUT, build_workbook_fn=build_workbook, derived_values=DERIVED)
    print("built", OUT)
